import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * The criteria a customer must satisfy to be part of a result set.
 *
 * <p>Both criteria are applied by the backend, so a filtered {@link Grid} stays
 * as lazy as an unfiltered one: {@link CustomerRepository} narrows the data set
 * before it pages or counts it.
 *
 * @param name     free text; split on whitespace into terms, each of which must
 *                 occur in the first or the last name. Matching ignores case and
 *                 accents. Blank text matches every customer.
 * @param statuses the statuses to keep; an empty set matches every customer.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null || statuses.isEmpty()) ? Set.of() : Set.copyOf(statuses);
    }

    /** A filter on the name only. */
    public static CustomerFilter byName(String name) {
        return new CustomerFilter(name, Set.of());
    }

    /** A filter on the status only. */
    public static CustomerFilter byStatus(Set<CustomerStatus> statuses) {
        return new CustomerFilter("", statuses);
    }

    /** {@code true} when this filter matches every customer. */
    public boolean isEmpty() {
        return statuses.isEmpty() && nameTerms().isEmpty();
    }

    /**
     * The name filter as case- and accent-folded search terms, in the order they
     * were typed. Empty when no name was entered.
     */
    public List<String> nameTerms() {
        String folded = fold(name);
        return folded.isEmpty() ? List.of() : List.of(WHITESPACE.split(folded));
    }

    /** {@code true} when {@code customer} satisfies both criteria. */
    public boolean matches(Customer customer) {
        return asPredicate().test(customer);
    }

    /**
     * This filter as a predicate. The search terms are folded once, so the
     * result is worth reusing across a whole result set.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = nameTerms();
        Set<CustomerStatus> allowed = statuses;
        return customer -> {
            if (!allowed.isEmpty() && !allowed.contains(customer.status())) {
                return false;
            }
            if (terms.isEmpty()) {
                return true;
            }
