        nameField().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(40));

        assertThat(summary()).hasText("Showing 15 of 500");
        assertEquals(15, GridElement.get(page).getTotalRowCount());

        int queries = queryLog.pageQueries().size() + queryLog.countQueries().size();
