     * Puts the filter in the address bar. It replaces the current history entry
     * instead of adding one: following the typing must not fill the back button
     * with a step for every pause.
     *
     * <p>The query string is written by hand rather than through
     * {@link QueryParameters#getQueryString()}, which would percent-escape the
     * separator of the status list into the unreadable {@code ACTIVE%2CCLOSED}.
     */
    private void writeUrl() {
        getUI().ifPresent(ui -> ui.getPage().executeJs(
                "window.history.replaceState(window.history.state, '', window.location.pathname + $0);"
                        + "window.dispatchEvent(new CustomEvent('vaadin-navigated'));",
                queryString(filter)));
    }

    /** The filter as a query string, empty when nothing is filtered. */
    static String queryString(CustomerFilter filter) {
        List<String> parameters = new ArrayList<>();
        String name = filter.name().strip();
        if (!name.isEmpty()) {
            parameters.add(NAME_PARAMETER + "=" + encode(name));
        }
        if (!filter.statuses().isEmpty()) {
            parameters.add(STATUS_PARAMETER + "=" + statusParameter(filter.statuses()));
        }
        return parameters.isEmpty() ? "" : "?" + String.join("&", parameters);
    }

    /** The selected statuses as a comma separated list, in declaration order. */
    private static String statusParameter(Set<CustomerStatus> statuses) {
        return statuses.stream().sorted().map(CustomerStatus::name).collect(Collectors.joining(","));
    }

    private static String encode(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
